for tic in T:
 g=G[tic];d=dict(verdict='CONFIRMED',assessment='Repeated discrete eclipses are present in raw QLP flux; representative event centers give a coherent eclipse period. Fresh independent aperture reduction and source localization are assessed below.',source='PENDING',geometry='',limitations='Representative review; no exhaustive event or sector fits. Independent custom extraction shares TESS photons with QLP. Pixel PRF and catalogue completeness limit astrometry; no formal calibrated PRF significance is claimed.',next_check='Optional improved spectroscopy and photometry would refine binary characterization.')
 if 'gaia_P' in g:
  c=g['conjunction'][g['closest_kind']];d['geometry']=f"Event-derived P={g['phot_P']:.9f} d; Gaia P={g['gaia_P']:.9f} +/- {g['gaia_P_error']:.9f} d. Difference {g['period_difference_gaia_sigma']:.2f} Gaia sigma is descriptive. Approximate conjunction {g['closest_kind']} offset {c['offset_d']:.3f} d; covariance linear error {c['covariance_linear_error_d']:.3f} d; conservative absolute-sum bound {c['conservative_sum_error_d']:.3f} d. Median fitted duration {g['observed_duration_hours_median']:.2f} h; approximate central duration {g['central_duration_hours_approx']:.2f} h. Geometry is physically feasible within approximate radii and propagated orbital phase uncertainty."
 if tic in ['12320469','450217907','86908196']:
  d.update(verdict='REFUTED',assessment='Three sector folds show smooth broad double-wave modulation, without a convincing discrete narrow eclipse. The original screen is refuted as an eclipsing interpretation of this measured signal.',source='Fresh cutouts were attempted; no established eclipse deficit exists to localize. Source attribution of the smooth modulation is not claimed.',geometry='The searched modulation period is not an eclipse-derived period. No conjunction comparison is claimed without established eclipses.',limitations='Smooth modulation may be ellipsoidal or other stellar variability; shallow additional eclipses are not excluded. A local trapezoid fit to a broad trend does not establish an eclipse.',next_check='Higher precision light curves could test for a narrow residual eclipse if further work on this smooth variable is desired.')
 if tic=='201317466':
  d['verdict']='PROBABLE';d['assessment']='Deep repeated eclipses are real and coherent. Association with the published Gaia SB1 orbit remains unresolved because its conjunction misses the eclipse by a substantial fraction of a cycle, beyond the conservative linear propagated uncertainty.';d['limitations']+=' Gaia has only 15 RV epochs, modestly constrained eccentricity (0.125 +/- 0.061), and strongly correlated periastron parameters. A 1.208 d conjunction offset versus 0.228 d linear covariance error and 0.694 d conservative sum bound is a physical phase discrepancy; no automatic sigma veto is applied.';d['next_check']='Refit the RV orbit or evaluate a nonlinear orbital posterior against the observed eclipse timing to resolve Gaia association.'
